import java.util.*;

class Solution {
  public boolean[] findAnswer(int n, int[][] edges) {
    List<int[]>[] graph = new List[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int i = 0; i < edges.length; i++) {
      graph[edges[i][0]].add(new int[] {edges[i][1], edges[i][2], i});
      graph[edges[i][1]].add(new int[] {edges[i][0], edges[i][2], i});
    }
    long[] fromStart = dijkstra(0, graph), fromEnd = dijkstra(n - 1, graph);
    boolean[] answer = new boolean[edges.length];
    long shortest = fromStart[n - 1];
    for (int i = 0; i < edges.length; i++) {
      int u = edges[i][0], v = edges[i][1], w = edges[i][2];
      answer[i] =
          fromStart[u] + w + fromEnd[v] == shortest || fromStart[v] + w + fromEnd[u] == shortest;
    }
    return answer;
  }

  private long[] dijkstra(int source, List<int[]>[] graph) {
    long[] dist = new long[graph.length];
    Arrays.fill(dist, Long.MAX_VALUE / 4);
    dist[source] = 0;
    PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
    pq.offer(new long[] {0, source});
    while (!pq.isEmpty()) {
      long[] cur = pq.poll();
      long d = cur[0];
      int u = (int) cur[1];
      if (d != dist[u]) continue;
      for (int[] e : graph[u])
        if (dist[e[0]] > d + e[1]) {
          dist[e[0]] = d + e[1];
          pq.offer(new long[] {dist[e[0]], e[0]});
        }
    }
    return dist;
  }
}
